insert into public.destinations(id,name,slug,country,region,description,hero_image_url,best_time_text,tips,budget_min_minor,budget_max_minor,currency,tags,latitude,longitude) values('20000000-0000-4000-8000-000000000001','Fort Kochi','fort-kochi','India','Kerala','Slow mornings, sea air and streets made for getting a little lost. Gather your people for art-filled lanes, old waterfronts and café detours.','https://images.unsplash.com/photo-1593693411515-c20261bcad6e?w=1000&auto=format&fit=crop','November–February is a commonly chosen cooler season; verify conditions before travel.','Pack light layers and water. Check venue hours locally. Respect places of worship and residential streets.',120000,300000,'INR',array['culture','food','relaxation']::text[],9.9658,76.2421) on conflict(id) do nothing;
insert into public.destinations(id,name,slug,country,region,description,hero_image_url,best_time_text,tips,budget_min_minor,budget_max_minor,currency,tags,latitude,longitude) values('20000000-0000-4000-8000-000000000002','Munnar','munnar','India','Kerala','Green hills, tea-scented air and the sort of views that make everyone put their phone down. Take it slow and leave time for misty mornings.','https://images.unsplash.com/photo-1593693397690-362cb9666fc2?w=1000&auto=format&fit=crop','Cooler months are popular; hill weather can change quickly.','Plan road transfers with a local operator. Trails and protected areas may have seasonal restrictions.',150000,350000,'INR',array['nature','adventure','photography']::text[],10.0889,77.0595) on conflict(id) do nothing;
insert into public.destinations(id,name,slug,country,region,description,hero_image_url,best_time_text,tips,budget_min_minor,budget_max_minor,currency,tags,latitude,longitude) values('20000000-0000-4000-8000-000000000003','Alleppey','alleppey','India','Kerala','A backwater state of mind. Watch palm trees drift past, share a slow lunch and trade the rush for a little water-side quiet.','https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?w=1000&auto=format&fit=crop','Drier months are often chosen for backwater trips; confirm local weather.','Choose licensed boat operators and check safety equipment. Boat prices vary widely and are not live quotes.',180000,450000,'INR',array['nature','relaxation','food']::text[],9.4981,76.3388) on conflict(id) do nothing;
insert into public.destinations(id,name,slug,country,region,description,hero_image_url,best_time_text,tips,budget_min_minor,budget_max_minor,currency,tags,latitude,longitude) values('20000000-0000-4000-8000-000000000004','Jaipur','jaipur','India','Rajasthan','Pink walls, busy bazaars and a camera roll full of colour. Go for the architecture; stay for the rooftop conversations and street-side snacks.','https://images.unsplash.com/photo-1599661046827-dacff0c0f09a?w=1000&auto=format&fit=crop','Cooler winter months are popular; summer afternoons can be very hot.','Ask before photographing people. Check ticket details at official counters; carry water.',140000,320000,'INR',array['culture','food','photography']::text[],26.9124,75.7873) on conflict(id) do nothing;
insert into public.destinations(id,name,slug,country,region,description,hero_image_url,best_time_text,tips,budget_min_minor,budget_max_minor,currency,tags,latitude,longitude) values('20000000-0000-4000-8000-000000000005','Gokarna','gokarna','India','Karnataka','Barefoot mornings and the long way to sunset. A beach-town break for friends who need fewer notifications and more sea air.','https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?w=1000&auto=format&fit=crop','Drier winter months are popular; respect monsoon warnings and local sea conditions.','Swimming conditions change. Follow local advice, take litter back and dress respectfully in town.',100000,250000,'INR',array['nature','relaxation','adventure']::text[],14.5479,74.3188) on conflict(id) do nothing;
